    (Decimal("100.00"), 3),
    (Decimal("10.00"), 7),
    (Decimal("0.05"), 3),
    (Decimal("0.01"), 100),
    (Decimal("999999.99"), 100),
]


def test_even_bill_gives_equal_shares() -> None:
    assert split_bill(Decimal("100.00"), 4) == [Decimal("25.00")] * 4


def test_uneven_bill_gives_the_extra_cent_to_the_first_guest() -> None:
    assert split_bill(Decimal("100.00"), 3) == [
        Decimal("33.34"),
        Decimal("33.33"),
        Decimal("33.33"),
    ]


def test_one_guest_pays_the_whole_bill() -> None:
    assert split_bill(Decimal("77.00"), 1) == [Decimal("77.00")]


def test_zero_bill_gives_zero_shares() -> None:
    assert split_bill(Decimal("0.00"), 2) == [Decimal("0.00"), Decimal("0.00")]


def test_leftover_cents_go_to_the_first_guests_one_each() -> None:
    assert split_bill(Decimal("10.00"), 7) == [Decimal("1.43")] * 6 + [Decimal("1.42")]
    assert split_bill(Decimal("0.05"), 3) == [Decimal("0.02"), Decimal("0.02"), Decimal("0.01")]


def test_one_share_per_guest() -> None:
    assert len(split_bill(Decimal("10.00"), 7)) == 7
    assert len(split_bill(Decimal("0.01"), 100)) == 100
    assert len(split_bill(Decimal("77.00"), 1)) == 1


def test_every_share_is_in_whole_cents() -> None:
    for amount, people in UNEVEN:
        for share in split_bill(amount, people):
            assert share == share.quantize(Decimal("0.01"))


