        shares = split_bill(amount, people)
        assert max(shares) - min(shares) <= Decimal("0.01")


def test_larger_shares_come_first() -> None:
    for amount, people in UNEVEN:
        shares = split_bill(amount, people)
        assert shares == sorted(shares, reverse=True)


def test_bounds_of_the_bill_and_of_the_guests_are_accepted() -> None:
    assert split_bill(Decimal("999999.99"), 1) == [Decimal("999999.99")]
    assert split_bill(Decimal("999999.99"), 100) == [Decimal("10000.00")] * 99 + [
        Decimal("9999.99")
    ]
    assert split_bill(Decimal("0.00"), 100) == [Decimal("0.00")] * 100


